import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("uploading a document returns 201 with status processing and records an audit event", { tag: "@DOC-01" }, async ({ apiAs }) => {
    // Arrange: a vendor in draft status
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Vendor"),
        category: "services",
        contact_email: `billing-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@acme-supply.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();
    expect(vendor.status).toBe("draft");

    // Act: upload insurance_certificate.txt as kind insurance_certificate
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("insurance_certificate.txt")),
        },
      },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(201);
    const doc = await res.json();
    expect(doc.status, await res.text()).toBe("processing");
    expect(doc.kind).toBe("insurance_certificate");
    expect(doc.vendor_id).toBe(vendor.id);

    const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
    expect(auditRes.status(), await auditRes.text()).toBe(200);
    const audit = await auditRes.json();
    const uploaded = audit.items.find((e: { action: string }) => e.action === "document.uploaded");
    expect(uploaded, JSON.stringify(audit)).toBeTruthy();
    expect(uploaded.details.document_id).toBe(doc.id);
  });
});
